        result.add(list);
        return result;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<Integer> left = new ArrayList<>();
        for (int j = 0; j < nums.length; j++) {
            if (j != i) {
                left.add(nums[j]);
