public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    // Calculate the length of the largest string
    int longest = 0;
    for (String string : strings) {
        longest = Math.max(longest, string.length());
    }

    // Iterate over each character in the largest string
    for (int i = 0; i < longest; i++) {
        // Check if the character is found in any of the given strings
        boolean found = false;
        for (String string : strings) {
            if (string.contains(String.valueOf(string.charAt(i)))) {
                found = true;
                break;
            }
        }
        if (!found) {
            // If the character is not found, we can return the length of the largest string
            return longest;
        }
    }

    // If we reach this point, we haven't found any characters that are not present in any of the given strings
    return -1;
}

