}

public static int maxRegions(int N) {
        if (N == 1) {
            return 2;
        }

        int maxRegions = 0;
        for (int i = 1; i <= N; i++) {
            if (i % 2 == 0) {
                maxRegions = Math.max(maxRegions, maxRegions(i) + maxRegions(N - i));
            } else {
                maxRegions = Math.max(maxRegions, maxRegions(i) + maxRegions(N - i) + 1);
            }
        }

        return maxRegions;
    }

