public double trimMean(int[] arr) {
    // Calculate the 5% lower boundary
    int lowerBound = (int) (arr.length * 0.05);
    Arrays.sort(arr);
    int[] sortedArr = Arrays.copyOfRange(arr, lowerBound, arr.length - lowerBound);

    // Calculate the sum of the remaining elements
    int sum = 0;
    for (int num : sortedArr) {
        sum += num;
    }

    // Return the mean with an error within 10^-5
    return (double) sum / sortedArr.length;
}

