    int totalToRemove = (int)Math.ceil(arr.length * 0.05);

    // Remove the smallest elements
    int[] temp = new int[arr.length - totalToRemove];
    for (int i = 0, j = 0; i < arr.length; i++) {
      if (i >= totalToRemove) {
        temp[j++] = arr[i];
      }
    }

    // Calculate the mean of the remaining elements
    int sum = 0;
    for (int i : temp) {
      sum += i;
    }
