public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    int nHalf = n / 2;

    // Create a hash table to keep track of the number of elements with a given remainder when divided by k
    int[] remainders = new int[k];

    // Iterate over the array and update the hash table
    for (int elem : arr) {
        // Get the remainder when dividing elem by k
        int remainder = elem % k;
        // Increment the count of elements with remainder in the hash table
        remainders[remainder]++;
    }

    // Iterate over the hash table and check if there are too many elements with the same remainder
    for (int i = 0; i < k; i++) {
        // If there are more than nHalf elements with remainder i, return false
        if (remainders[i] > nHalf) {
            return false;
        }
    }

    // If no elements have more than nHalf elements with the same remainder, return true
    return true;
}

