    int[] sum = new int[n];
    sum[0] = arr[0];
    for (int i = 1; i < n; i++) {
        sum[i] = sum[i - 1] + arr[i];
    }
    for (int i = 0; i < n / 2; i++) {
        if (sum[i * 2] % k == 0 && sum[(i * 2) + 1] % k == 0) {
            return true;
        }
    }
    return false;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n];
    int time = 0;

    // Start at node 0
    queue.offer(0);
    visited[0] = true;

    // Breadth-first search
    while (!queue.isEmpty()) {
        int currentNode = queue.poll();
        time++;

        // If the current node has an apple, add the time
        if (hasApple[currentNode]) {
            return time;
        }

        // Enqueue the neighbors
        for (int neighbor : edges[currentNode]) {
            if (!visited[neighbor]) {
                queue.offer(neighbor);
                visited[neighbor] = true;
            }
        }
    }

    // If we reach this point, there are no apples
    return 0;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a boolean array to keep track of which nodes have been visited
    boolean[] visited = new boolean[n];

    // Initialize a queue to hold the nodes to be visited
    Queue<Integer> queue = new LinkedList<>();

    // Add node 0 to the queue and mark it as visited
    queue.add(0);
    visited[0] = true;

    // Initialize a variable to keep track of the time
    int time = 0;

    while (!queue.isEmpty()) {
        // Get the size of the queue
        int size = queue.size();

        // Iterate through the queue
        for (int i = 0; i < size; i++) {
            // Get the current node
            int node = queue.poll();

            // If the current node has an apple and it has not been visited before, mark it as visited and add it to the queue
            if (hasApple[node] && !visited[node]) {
                visited[node] = true;
                queue.add(node);
            }

            // Iterate through the neighbors of the current node
            for (int neighbor : edges[node]) {
                // If the neighbor has not been visited before, mark it as visited and add it to the queue
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    queue.add(neighbor);
                }
            }
        }

        // Increment the time
        time++;
    }

    // Return the time
    return time;
}

