public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize the distances and parent arrays
    int[] distances = new int[n];
    int[] parents = new int[n];

    // Initialize the queue and the distance of the starting node to 0
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    distances[0] = 0;
    parents[0] = -1;

    // BFS to find the shortest distance from the starting node to all other nodes
    while (!queue.isEmpty()) {
        // Get the current node and its distance from the starting node
        int current = queue.poll();
        int distance = distances[current];

        // Loop through the neighbors of the current node
        for (int neighbor : edges[current]) {
            // If the neighbor has not been visited before
            if (distances[neighbor] == 0) {
                // Mark the neighbor as visited and add it to the queue
                queue.offer(neighbor);
                distances[neighbor] = distance + 1;
                parents[neighbor] = current;
            }
        }
    }

    // Initialize the time and the current node
    int time = 0;
    int current = 0;

    // Loop until all apples are collected
    while (hasApple[current]) {
        // If the current node has an apple
        if (hasApple[current]) {
            // Collect the apple and update the time
            time += distances[current];
            hasApple[current] = false;
        }

        // Update the current node to its parent
        current = parents[current];
    }

    // Return the final time
    return time;
}

public String sortString(String s) {
    if (s.isEmpty()) return "";

    ArrayList<Character> chars = new ArrayList<>(s.length());
    for (char c : s.toCharArray()) chars.add(c);

    char smallest = ' '; // smallest character in the string so far
    char largest = ' '; // largest character in the string so far
    int smallestIndex = 0; // index of the smallest character
    int largestIndex = 0; // index of the largest character

    // sort the string in the specified order
    while (!chars.isEmpty()) {
      // pick the smallest character that is not yet picked
      int smallestIndex = -1;
      for (int i = 0; i < chars.size(); i++) {
        char c = chars.get(i);
        if (c < smallest && c > largest) {
          smallestIndex = i;
          smallest = c;
        }
      }

      if (smallestIndex == -1) {
        smallestIndex = chars.size() - 1;
        smallest = chars.get(smallestIndex);
      }

      // pick the largest character that is at most the last picked
      int largestIndex = -1;
      for (int i = chars.size() - 1; i >= 0; i--) {
        char c = chars.get(i);
        if (c >= largest && c < smallest) {
          largestIndex = i;
          largest = c;
        }
      }

      if (largestIndex == -1) {
        largestIndex = 0;
        largest = chars.get(largestIndex);
      }

      // append the picked characters to the result
      StringBuilder result = new StringBuilder();
      result.append(smallest);
      result.append(largest);

      // remove the picked characters from the original string
      chars.remove(smallestIndex);
      chars.remove(largestIndex);

      // update the smallest and largest characters and their indices
      smallest = ' ';
      largest = ' ';
      smallestIndex = 0;
      largestIndex = 0;

      // check if the result contains all characters in the original string
      if (result.length() == s.length()) {
        return result.toString();
      }
    }

    return ""; // will never reach here since s is not empty
  }

