    double average = (double) sum / nums.length;

    // Check if the average is an integer
    if (average % 1 == 0) {
        // If the average is an integer, check if it is possible to split the array into two arrays with that average
        return canSplitArray(nums, (int) average);
    }

    // If the average is not an integer, check if it is possible to split the array into two arrays with two closest integers to the average
    int closestIntAverage = (int) Math.round(average);
    return canSplitArray(nums, closestIntAverage - 1) || canSplitArray(nums, closestIntAverage + 1);
}

