      return true;
    }
  }
  return false;
}

public boolean hasAllCodes(String s, int k) {
  // Check if k is valid
  if (k <= 0 || k > s.length()) {
    return false;
  }

  // Initialize a set to keep track of substring frequencies
  Set<String> substrings = new HashSet<>();

  // Loop through each substring of length k in s
  for (int i = 0; i < s.length() - k + 1; i++) {
    String substring = s.substring(i, i + k);
    if (!substrings.contains(substring)) {
      substrings.add(substring);
    } else {
      return false;
    }
  }

  // If all substrings are unique, return true
  return true;
}

public boolean hasAllCodes(String s, int k) {
    int windowStart = 0;
    int windowEnd = 0;
    int substringLength = k;

    while (windowEnd < s.length()) {
        if (substringLength == s.substring(windowStart, windowEnd + 1).length()) {
            windowStart++;
            windowEnd++;
            substringLength--;
        } else {
            windowEnd++;
        }
    }

    return substringLength == 0;
}

