        if (n % i == 0) {
            numDivisors++;
            if (i != n / i) {
                numDivisors++;
            }
        }
    }

    // If the number of divisors is less than k, return -1
    if (numDivisors < k) {
        return -1;
    }

    // Calculate the kth divisor
    int divisor = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            divisor++;
            if (divisor == k) {
                return i;
