public int maxUniqueSplit(String s) {
    // Initialize a set to store unique substrings
    Set<String> uniqueSubstrings = new HashSet<>();

    // Loop through each character in the string
    for (int i = 0; i < s.length(); i++) {
        // Initialize a substring to store the current character
        String substring = "";

        // Add the current character to the substring
        substring += s.charAt(i);

        // Add the substring to the set if it is unique
        if (!uniqueSubstrings.contains(substring)) {
            uniqueSubstrings.add(substring);
        }

        // Add the rest of the characters in the string to the substring
        for (int j = i + 1; j < s.length(); j++) {
            substring += s.charAt(j);

            // If the substring is not unique, break out of the loop
            if (uniqueSubstrings.contains(substring)) {
                break;
            }

            // Add the substring to the set if it is unique
            uniqueSubstrings.add(substring);
        }
    }

    // Return the maximum number of unique substrings
    return uniqueSubstrings.size();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() < 1) {
        return 0;
    }
    // create a map to keep track of the unique substrings
    Map<String, Integer> uniqueSubstrings = new HashMap<>();
    int max = 0;
    int current = 0;
    for (int i = 0; i < s.length(); i++) {
        // split the string on the current character
        String[] split = s.substring(0, i).split(s.charAt(i) + "");
        // add the substrings to the map
        for (String substring : split) {
            uniqueSubstrings.put(substring, 1);
        }
        // update the current count and maximum
        current = uniqueSubstrings.size();
        max = Math.max(max, current);
        // remove any substrings that have already appeared in the map
        for (String substring : split) {
            uniqueSubstrings.remove(substring);
        }
    }
    return max;
}

