public int minOperations(String[] logs) {
    int minOperations = 0;
    Stack<String> folderStack = new Stack<>();
    folderStack.push("");
    for (String log : logs) {
        if (log.equals("../")) {
            if (folderStack.isEmpty()) {
                minOperations++;
            } else {
                folderStack.pop();
            }
        } else if (log.equals("./")) {
            // Do nothing
        } else {
            folderStack.push(log);
        }
    }
    while (!folderStack.isEmpty()) {
        folderStack.pop();
        minOperations++;
    }
    return minOperations;
}

