    /** This method calculates the probability that the last passenger will sit in their own seat.
     * @param n The number of passengers.
     * @return The probability that the last passenger will sit in their own seat.
     */
    double emptySeatChance = 1 / (double) n;
    double occupiedSeatChance = 1 - emptySeatChance;
    double probability = BinomialDistribution.discrete(n - 1,
            occupiedSeatChance).probability(n - 1) /
            BinomialDistribution.discrete(n - 1,
            occupiedSeatChance).cumulativeProbability(n - 1);
    return probability;
  }

