  List<Integer> steppingNumbers = new ArrayList<>();

  // Iterate through each digit in the range
  for (int i = low; i <= high; i++) {
    int[] digits = toDigits(i);
    boolean isSteppingNumber = true;

    // Check if each digit is within 1 step of the previous digit
    for (int j = 1; j < digits.length; j++) {
      if (Math.abs(digits[j] - digits[j-1]) > 1) {
        isSteppingNumber = false;
        break;
      }
    }

    // If the number is a stepping number, add it to the list
    if (isSteppingNumber) {
      steppingNumbers.add(i);
    }
  }

  // Sort the list of stepping numbers
  steppingNumbers.sort(Comparator.naturalOrder());

  return steppingNumbers;
}

