public static int longestLine(int[][] mat) {
    // Find the longest line by scanning the matrix
    // from top to bottom, left to right.
    int m = mat.length, n = mat[0].length;
    int maxLength = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                int length = 1;
                // Check if there are any 1s to the left and
                // above the current index.
                while (i - length >= 0 && j - length >= 0 && mat[i - length][j - length] == 1) {
                    length++;
                }
                // Check if there are any 1s to the right and
                // below the current index.
                while (i + length < m && j + length < n && mat[i + length][j + length] == 1) {
                    length++;
                }
                maxLength = Math.max(maxLength, length);
            }
        }
    }
    return maxLength;
}

