public static int squarePermutations(int[] A) {
    int[] B = new int[A.length];
    int[] C = new int[A.length];
    boolean[] visited = new boolean[A.length];

    for (int i = 0; i < A.length; i++) {
        B[i] = A[i];
        visited[i] = false;
    }

    int count = 0;
    while (true) {
        boolean found = false;
        for (int i = 0; i < A.length; i++) {
            if (!visited[i]) {
                for (int j = i + 1; j < A.length; j++) {
                    if (!visited[j]) {
                        if ((B[i] + B[j]) % 2 == 0 && Math.sqrt((double) (B[i] + B[j])) == Math.floor(Math.sqrt((double) (B[i] + B[j])))) {
                            found = true;
                            break;
                        }
                    }
                }
                if (found) {
                    break;
                }
            }
        }
        if (!found) {
            break;
        }

        for (int i = 0; i < A.length; i++) {
            if (!visited[i]) {
                visited[i] = true;
                C[i] = B[i];
                B[i] = B[A.length - 1 - i];
                B[A.length - 1 - i] = C[i];
            }
        }

        count++;
    }

    return count;
}

