                block[i] = block[i - 1];
            } else {
                block[i] = block[i - 1] + 1;
                if (block[i] > 1) {
                    return 0;
                }
            }

            if (i > 1 && A[i - 1] + A[i] > 0) {
                int sum = A[i - 1] + A[i];
                int k = (int)Math.sqrt(sum);
                if (k * k == sum) {
                    marked[i] = 1;
                    counts[i]--;
                    counts[i - 1]--;
                }
            }
        }

        int n = 0;
        for (int i = 0; i < A.length; i++) {
            if (marked[i] == 0) {
                n++;
            }
        }

        return n;
    }

public static int squarePermutations(int[] A) {
        int count = 0;
        for (int i = 0; i < A.length; i++) {
            for (int j = i + 1; j < A.length; j++) {
                if (Math.pow(A[i] + A[j], 0.5) == (A[i] + A[j])) {
