public static int squarePermutations(int[] A) {
    // Check if the given array is square by checking if the sum of each pair of adjacent elements is a perfect square
    int sum;
    for (int i = 0; i < A.length - 1; i++) {
        sum = A[i] + A[i + 1];
        if (sum % 2 == 0 && Math.sqrt(sum) == (int) Math.sqrt(sum)) {
            // If the sum is a perfect square, continue checking the next pair of adjacent elements
            continue;
        } else {
            // If the sum is not a perfect square, return 0
            return 0;
        }
    }

    // The given array is square, count the number of permutations
    int count = 0;
    for (int i = 0; i < A.length; i++) {
        int temp = A[i];
        A[i] = 0;
        count += factorial(A.length - 1) / (factorial(i) * factorial(A.length - i - 1));
        A[i] = temp;
    }

    return count;
}

