public static int findSmallestInteger(int n) {
        if (n < 10)
            return -1;

        ArrayList<Integer> digits = new ArrayList<>();

        while (n > 0) {
            digits.add(n % 10);
            n /= 10;
        }

        Collections.sort(digits);

        int result = 0;

        for (int i = digits.size() - 1; i >= 0; i--) {
            result += (int)Math.pow(10, digits.size() - i - 1) * digits.get(i);
        }

        return result;
    }

