    int[] digits = new int[10];
    for (int i = 0; i < 10; i++) {
        digits[i] = (n % 10) + 1;
        n /= 10;
    }
    Arrays.sort(digits);

    // Rearrange the digits
    int result = 0;
    for (int i = 9; i >= 0; i--) {
        result = (result * 10) + digits[i];
    }

    // Check if the result is greater than the input
    if (result <= n) {
        return -1;
    }
    return result;
}

