    }
    int count = 1;
    while (count <= n) {
        String number = new String(digits);
        if (number.compareTo("0") == 0 || number.compareTo("1") == 0) {
            count++;
            continue;
        }
        numbers.add(number);
        digits[0] = Character.forDigit(count, 10);
        count++;
    }
    return numbers;
