public static boolean isBoomerang(int[][] points) {
    int[] dist1 = {points[1][0] - points[0][0], points[1][1] - points[0][1]};
    int[] dist2 = {points[2][0] - points[1][0], points[2][1] - points[1][1]};
    int[] cross = {dist1[1] * dist2[0] - dist1[0] * dist2[1], dist1[0] * dist2[0] + dist1[1] * dist2[1]};
    return cross[0] < 0;
}

