    int[] diffX = new int[points.length];
    int[] diffY = new int[points.length];
    for (int i = 0; i < points.length; i++) {
        diffX[i] = points[i][0] - points[(i + 1) % points.length][0];
        diffY[i] = points[i][1] - points[(i + 1) % points.length][1];
    }
    int crossProduct = diffX[0] * diffY[1] - diffX[1] * diffY[0];
    return crossProduct == 0 && diffX[0] != 0 && diffY[0] != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }
    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];
    int xc = x2 - x1;
    int yc = y2 - y1;
    int xd = x3 - x1;
    int yd = y3 - y1;
    return xc * yd - yc * xd != 0;
}

public static boolean isBoomerang(int[][] points) {
  if (points == null || points.length != 3) {
    throw new IllegalArgumentException("Invalid input");
  }

  int[][] differences = new int[3][2];

  // Calculate differences between each pair of points
  for (int i = 0; i < 3; i++) {
    for (int j = i + 1; j < 3; j++) {
      if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
        return false; // two points are equal
      }
      differences[i][0] += points[j][0] - points[i][0];
      differences[i][1] += points[j][1] - points[i][1];
    }
  }

  // Check area of triangle
  int area = differences[0][0] * differences[1][1] - differences[0][1] * differences[1][0];
  return (area > 0);
}

public static int findNthUglyNumber(int n) {
  Queue<Integer> queue = new LinkedList<Integer>();
  queue.offer(1);

  for (int i = 1; i < n; i++) {
    int curr = queue.poll();
    int mult2 = 2 * curr;
    int mult3 = 3 * curr;
    int mult5 = 5 * curr;

    int min = Math.min(Math.min(mult2, mult3), mult5);
    queue.offer(min);
  }

  return queue.poll();
}

public static int findNthUglyNumber(int n) {
