  int[] factors = new int[] { 2, 3, 5 };
  int[] nums = new int[n];
  nums[0] = 1;

  for (int i = 1; i < n; i++) {
    int factor = factors[nums[i - 1] % 3];
    nums[i] = factor * (nums[i - 1] / factor + 1);
  }

  return nums[n - 1];
}

