	}

	int[] factors = { 2, 3, 5 };
	int[] factorIndexes = { 0, 0, 0 };
	int[] uglyNumbers = { 1, 1, 1 };

	for (int i = 2; i < n; i++) {
		int minFactor = Integer.MAX_VALUE;
		for (int j = 0; j < factors.length; j++) {
			minFactor = Math.min(minFactor, factors[j] * uglyNumbers[factorIndexes[j]]);
		}
		uglyNumbers[i] = minFactor;
		for (int j = 0; j < factors.length; j++) {
			if (minFactor == factors[j] * uglyNumbers[factorIndexes[j]]) {
				factorIndexes[j]++;
			}
		}
	}

	return uglyNumbers[n - 1];
}

public static int findNthUglyNumber(int n) {
