    int[] uglyNumbers = new int[n];

    // Initialize three pointers for the three sequences of prime factors: 2, 3, and 5
    int twoPointer = 0;
    int threePointer = 0;
    int fivePointer = 0;

    // Initialize the first ugly number
    uglyNumbers[0] = 1;

    // Loop through the rest of the ugly numbers
    for (int i = 1; i < n; i++) {
        // Determine the next ugly number based on the three sequences
        int nextUglyNumber = Math.min(
                2 * uglyNumbers[twoPointer] * uglyNumbers[twoPointer],
                Math.min(3 * uglyNumbers[threePointer] * uglyNumbers[threePointer],
                        5 * uglyNumbers[fivePointer] * uglyNumbers[fivePointer]));

        // Update the pointers
        if (nextUglyNumber == 2 * uglyNumbers[twoPointer] * uglyNumbers[twoPointer]) {
            twoPointer++;
        }
        if (nextUglyNumber == 3 * uglyNumbers[threePointer] * uglyNumbers[threePointer]) {
            threePointer++;
        }
        if (nextUglyNumber == 5 * uglyNumbers[fivePointer] * uglyNumbers[fivePointer]) {
            fivePointer++;
        }

        // Store the next ugly number
        uglyNumbers[i] = nextUglyNumber;
    }

    return uglyNumbers[n - 1];
}

public static int calculateEnergy(String s) {
        if (s == null || s.length() < 1) {
            return 0;
        }

        int maxLength = 0, start = 0, end = 0;
        for (int i = 0; i < s.length(); i++) {
            int currentLength = 1, count = 1;
            for (int j = i + 1; j < s.length(); j++) {
                if (s.charAt(i) == s.charAt(j)) {
                    count++;
                } else {
                    break;
                }
            }
            if (count > maxLength) {
                maxLength = count;
                start = i;
                end = i + count - 1;
            }
        }

        return end - start + 1;
    }

