    for (int i = 1; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            count++;
            if (i * i != n) {
                count++;
            }
        }
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
   List<Integer> squares = new ArrayList<>();
   for (int i = 1; i * i <= n; i++) {
       squares.add(i * i);
   }
   Arrays.sort(squares);
   int count = 0;
   int sum = 0;
   for (int square : squares) {
       sum += square;
       if (sum > n) {
           break;
       }
       count++;
   }
   return count;
}

