public static String reverseWords(String s) {
    // Using String.split() to split the input string into an array of words
    String[] words = s.split(" ");
    // Creating a string builder to store the reversed words
    StringBuilder revWords = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        // Reversing each word
        String word = new StringBuilder(words[i]).reverse().toString();
        // Appending the reversed word to the string builder
        revWords.append(word);
        // Appending a space if not the last word
        if (i < words.length - 1) {
            revWords.append(" ");
        }
    }
    return revWords.toString();
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder reversedSentence = new StringBuilder();

    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        reversedSentence.append(reversedWord.toString());
        reversedSentence.append(" ");
    }

    // Trim the last space and return the result
    return reversedSentence.toString().replaceAll("( )+", " ").trim();
}

